package library.string;
import library.engine.IntList;
public class KMPSearch { private int[] pi(String p){int[] a=new int[p.length()];for(int i=1,j=0;i<p.length();i++){while(j>0&&Character.toLowerCase(p.charAt(i))!=Character.toLowerCase(p.charAt(j)))j=a[j-1];if(Character.toLowerCase(p.charAt(i))==Character.toLowerCase(p.charAt(j)))j++;a[i]=j;}return a;} public boolean contains(String t,String p){return search(t,p)>=0;} public int search(String t,String p){if(p.length()==0)return 0;int[] a=pi(p);for(int i=0,j=0;i<t.length();i++){while(j>0&&Character.toLowerCase(t.charAt(i))!=Character.toLowerCase(p.charAt(j)))j=a[j-1];if(Character.toLowerCase(t.charAt(i))==Character.toLowerCase(p.charAt(j)))j++;if(j==p.length())return i-j+1;}return -1;} public IntList searchAll(String t,String p){IntList r=new IntList();if(p.length()==0){r.add(0);return r;}int[] a=pi(p);for(int i=0,j=0;i<t.length();i++){while(j>0&&Character.toLowerCase(t.charAt(i))!=Character.toLowerCase(p.charAt(j)))j=a[j-1];if(Character.toLowerCase(t.charAt(i))==Character.toLowerCase(p.charAt(j)))j++;if(j==p.length()){r.add(i-j+1);j=a[j-1];}}return r;} }
